import{_ as d,o as e,c as i,ag as a}from"./chunks/framework.C9sp7nFj.js";const s="/images/movcircle-diagram.png",E=JSON.parse('{"title":"MovCircle 整圆指令","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovCircle.md","filePath":"3. 指令/1. 运动指令/MovCircle.md","lastUpdated":1778862643000}'),r={name:"3. 指令/1. 运动指令/MovCircle.md"};function o(l,t,n,c,h,p){return e(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="movcircle-整圆指令" tabindex="-1">MovCircle 整圆指令 <a class="header-anchor" href="#movcircle-整圆指令" aria-label="Permalink to &quot;MovCircle 整圆指令&quot;">​</a></h1><p>整圆指令指机器人 TCP 点从起始位置，经过辅助点 1 与辅助点 2 位置回到起始位置做整圆运动。在整圆运动过程中，机器人的姿态保持不变。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovCircle(A, P, [V], [B], [C], [Tool], [Coord], [PayLoad], [O], [DO])</p><p>MovCircle(中间点, 目标点, [速度], [平滑], [姿态], [工具], [坐标系], [负载], [姿态控制], [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>A</td><td>APOS 或 CPOS 变量</td><td>整圆中间辅助点位置 1，用于确定圆弧大小和运动方向，该点的姿态不会影响最终轨迹的运行。</td><td>必填</td></tr><tr><td>P</td><td>APOS 或 CPOS 变量</td><td>整圆中间辅助点位置 2，用于确定圆弧大小和运动方向，该点的姿态不会影响最终轨迹的运行。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>用于指定机器人执行 MovCircle 时的速度，包括机器人末端的平移速度、旋转速度以及外部轴的移动速度等。SPEED 变量中的 <code>tcp</code>、<code>ori</code> 分量有效；有外部轴时，<code>exj_l</code>、<code>exj_r</code> 分量有效。</td><td>可选，默认 V4000</td></tr><tr><td>[B]</td><td>enum（FINE / RELATIVE / ABSOLUTE / DEFAULT）</td><td>机器人逼近终点时的过渡方式：<br><code>FINE</code>：无过渡。<br><code>RELATIVE</code>：相对过渡。<br><code>ABSOLUTE</code>：绝对过渡。<br><code>DEFAULT</code>：缺省类型。</td><td>可选，默认 FINE</td></tr><tr><td>[C]</td><td>ZONE 变量</td><td>机器人逼近终点时的过渡值。</td><td>可选，默认 C100</td></tr><tr><td>[Tool]</td><td>TOOL 变量</td><td>机器人执行该轨迹时使用的工具参数。</td><td>可选，默认使用当前系统中设置的工具参数</td></tr><tr><td>[Coord]</td><td>USERCOOR 变量 / EXTTCP 变量 / 变位机变量</td><td>机器人执行该轨迹时使用的用户坐标系 / 外部 TCP 坐标系 / 变位机坐标系。</td><td>可选，默认使用当前系统中设置的坐标系参数</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的工件负载参数。</td><td>可选，默认使用当前系统中设置的负载参数</td></tr><tr><td>[O]</td><td>enum（GOVRON / GOVROFF）</td><td><code>GOVRON</code>：本段轨迹受全局速度倍率影响。<br><code>GOVROFF</code>：本段轨迹不受全局速度倍率影响。</td><td>可选，默认 GOVRON</td></tr><tr><td>[DO]</td><td>string</td><td>机器人执行完该指令后，可触发的 IO 操作，目前支持的 IO 指令有：<code>SetDO</code>、<code>SetAO</code>、<code>SetSimDO</code>、<code>SetSimAO</code>、<code>PulseOut</code>、<code>PulseSimOut</code>、<code>SetDO8421</code>、<code>SetSimDO8421</code>、<code>SetDIEdge</code>、<code>SetSimDIEdge</code>。</td><td>可选</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovCircle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, P2, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, DO1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>机器人从当前位置出发，经过中间点 <strong>P1</strong>，最终运动到目标点 <strong>P2</strong>，形成一段圆弧轨迹。</p><p><img src="'+s+'" alt=""></p>',15)])])}const C=d(r,[["render",o]]);export{E as __pageData,C as default};
